export function resolveDiagramsForConnector(
  connector: string,
  platformId?: string,
): ProcedureImage[] {
  if (platformId === 'whirlpool_duet_sport_dryer') {
    const ids = W8178559_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W8178559_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  if (platformId === 'whirlpool_tl_dd') {
    const ids = W10864849_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W10864849_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  if (platformId === 'whirlpool_dishwasher_acu') {
    const ids = W11633848_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W11633848_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  if (platformId === 'whirlpool_ccu_dryer') {
    const w108Ids = W10881701_CONNECTOR_DIAGRAM_IDS[connector];
    if (w108Ids?.length) {
      return w108Ids
        .map((id) => W10881701_DIAGRAMS[id] ?? W10680150_DIAGRAMS[id])
        .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
    }
    const ids = W10680150_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W10680150_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  if (platformId === 'whirlpool_acu_tl_dryer') {
    const ids = W11416805_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W11416805_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  if (platformId === 'whirlpool_mvw6200') {
    const ids = W11416395_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W11416395_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  if (platformId === 'whirlpool_tl_dd_5100') {
    const ids = W11416787_CONNECTOR_DIAGRAM_IDS[connector] || [];
    return ids
      .map((id) => W11416787_DIAGRAMS[id])
      .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
  }

  const catalog =
    platformId === 'whirlpool_duet_sport'
      ? W8178558_DIAGRAMS
      : W11169652_DIAGRAMS;
  const connectorMap =
    platformId === 'whirlpool_duet_sport'
      ? W8178558_CONNECTOR_DIAGRAM_IDS
      : CONNECTOR_DIAGRAM_IDS;
  const ids = connectorMap[connector] || [];
  return ids
    .map((id) => catalog[id])
    .filter((item): item is ProcedureImage => Boolean(item?.assetPath));
}

export function serializeProcedureImages(images: ProcedureImage[]): ProcedureImage[] {
  return images.map(({ id, caption, assetPath }) => ({ id, caption, assetPath }));
}
